import {esc,head,panel,button,badge,select,field,note,table,errors,submit,empty,link,icon} from './view.js';
import {resultLabel} from './result.js';
import {pieceIcon} from './board.js';
const kinds=[['rock','Búa'],['paper','Lá'],['scissors','Kéo']];
const patterns=[['orthogonal','Thẳng'],['diagonal','Chéo'],['king','8 hướng'],['knight','Nhảy chữ L']];
const number=(label,name,value,min,max)=>field(label,name,`required min="${min}" max="${max}" step="1"`,'number',value);
export const ruleFingerprint=value=>JSON.stringify(value,(_key,item)=>item&&typeof item==='object'&&!Array.isArray(item)?Object.fromEntries(Object.keys(item).sort().map(k=>[k,item[k]])):item);
export function rulesetField(s,selected='',toggle=false){
 const catalog=s.rulesetCatalog,items=catalog?.enabled?catalog.items.filter(x=>x.status==='published'):[];
 selected=items.some(r=>r.id===selected)?selected:'';
 const choices=[['','OTT v2 tiêu chuẩn'],...items.map(r=>[r.id,r.definition.name+' · v'+r.version+' · Experimental'])];
 return `<div class="ruleset-choice">${toggle?`<label class="switch-label"><input type="checkbox" role="switch" name="use-experimental" ${selected&&catalog?.enabled?'checked':''} ${catalog?.enabled?'':'disabled'}><span class="switch-track" aria-hidden="true"></span><strong>Ruleset add-on</strong></label>`:''}<label class="field" ${toggle?'data-experimental-select '+(selected&&catalog?.enabled?'':'hidden'):''}><span>Bộ luật</span>${select('ruleset_id',choices,catalog?.enabled?selected:'',!!selected)}</label>${catalog?.enabled?note('Add-on dùng SDK v3. Benchmark phải khớp ruleset và thời gian của giải.'):note('Ruleset add-on đang tắt. BTC có thể bật trong thư viện ruleset.')}</div>`;
}
// SDK v3 does not imply that every uploaded bot also speaks classic v2.
// Require an explicit selection instead of silently sending a classic job.
export function botRulesetField(s,ids,selected=''){
 const submissions=ids.map(id=>s.submissions.find(x=>x.id===id)).filter(Boolean);
 const extended=submissions.some(x=>x.protocol_version===3),catalog=s.rulesetCatalog;
 const items=catalog?.enabled?catalog.items.filter(x=>x.status==='published'):[];
 const value=selected==='classic'||items.some(x=>x.id===selected)?selected:selected?'':extended?'':'classic';
 const choices=[...(extended||selected&&!value?[['','Chọn bộ luật để chạy bot']]:[]),['classic','OTT v2 tiêu chuẩn · protocol v2'],...items.map(r=>[r.id,r.definition.name+' · v'+r.version+' · Experimental / SDK v3'])];
 const help=extended?(!catalog?.enabled?'Bot có SDK v3. Experimental đang tắt; BTC cần bật và công bố ruleset. Chỉ chọn classic nếu code bot cũng hỗ trợ protocol v2.':!items.length?'Experimental đã bật nhưng chưa có ruleset được công bố. BTC cần tạo luật → Kiểm tra (Validate) → Công bố (Publish). Bot minimax SDK v3 cần chọn một ruleset experimental.':'Bot có SDK v3. Chọn ruleset experimental đã công bố; classic chỉ dùng được nếu bot cũng hỗ trợ protocol v2.'):'Bot SDK v2 dùng luật classic. Muốn dùng experimental, nộp phiên bản SDK v3 trước.';
 return `<div class="ruleset-choice" data-bot-ruleset><label class="field"><span>Bộ luật / giao thức chạy</span>${select('ruleset_id',choices,value)}</label>${note(help)}${link(value&&value!=='classic'?'rulesets/'+value:'rulesets','Chi tiết luật & nước đi hợp lệ','small')}</div>`;
}
export function botRulesetSelection(s,ids,value){
 if(!value)throw new Error('Chưa chọn bộ luật. Bot minimax SDK v3 cần ruleset experimental đã công bố; BTC phải tạo, kiểm tra và công bố luật trước.');
 if(value==='classic')return {};
 if(!s.rulesetCatalog?.enabled||!s.rulesetCatalog.items.some(x=>x.id===value&&x.status==='published'))throw new Error('Ruleset experimental chưa được công bố hoặc đang tắt. Hãy cập nhật danh sách và chọn lại.');
 if(ids.some(id=>s.submissions.find(x=>x.id===id)?.protocol_version!==3))throw new Error('Experimental yêu cầu tất cả bot đã nộp với SDK v3. Hãy chọn đúng phiên bản bot.');
 return {ruleset_id:value};
}
export function modifierRow(m,i){
 return `<fieldset class="rule-modifier" data-modifier="${i}"><legend>Mẫu đi ${i+1}</legend><div class="form-grid">${field('ID kỹ năng','mod-'+i+'-id','required pattern="[a-z][a-z0-9_-]{0,23}"','text',m.id)}<label class="field"><span>Mẫu di chuyển</span>${select('mod-'+i+'-pattern',patterns,m.pattern)}</label>${number('Tầm tối đa','mod-'+i+'-range',m.range,1,3)}${number('Năng lượng','mod-'+i+'-cost',m.cost,0,9)}${number('Chờ hồi kỹ năng (lượt của đội)','mod-'+i+'-cooldown',m.cooldown,0,8)}${field('ID quân (phân cách bằng dấu phẩy)','mod-'+i+'-ids','placeholder="red-a2, blue-i8"','text',(m.filter.piece_ids||[]).join(', '))}</div><div class="rule-kind-filter">${kinds.map(([k,label])=>`<label class="check-field"><input type="checkbox" name="mod-${i}-${k}" ${!m.filter.kinds?.length||m.filter.kinds.includes(k)?'checked':''}>${pieceIcon(k)}${label}</label>`).join('')}</div>${button('Bỏ mẫu đi','rule-remove-modifier',`data-index="${i}"`,'small danger-button')}</fieldset>`;
}
export function ruleEditor(d,r,releaseNotes=r?.release_notes||''){
 const zones=new Map(d.zones.map(z=>[z.square,z]));
 return `<form class="real-form" id="ruleset-form">${field('Tên bộ luật','rule-name','required minlength="3" maxlength="80"','text',d.name)}<label class="field"><span>Ghi chú thay đổi cho đội thi</span><textarea class="input" name="release-notes" rows="3" maxlength="2000" placeholder="Ví dụ: Kéo có thể đi thẳng 2 ô; giữ vùng trung tâm để tích điểm.">${esc(releaseNotes)}</textarea></label><div class="form-grid">${number('Năng lượng tối đa','energy-cap',d.energy.cap,0,9)}${number('Năng lượng ban đầu','energy-initial',d.energy.initial,0,9)}</div><h3>Vùng trên bàn cờ</h3><p class="muted">Nhấn ô để đổi: thường → năng lượng → kiểm soát. Căn cứ được giữ riêng. Vùng cộng 1 mỗi lượt; JSON cho phép đổi gain từ 1–3.</p><div class="rule-map" role="group" aria-label="Thiết kế vùng bàn cờ">${Array.from({length:81},(_,i)=>{const square=String.fromCharCode(97+i%9)+(9-Math.floor(i/9)),z=zones.get(square);return `<button type="button" class="rule-map-cell ${z?'zone-'+z.kind:''}" data-action="rule-zone" data-square="${square}" data-kind="${z?.kind||''}" data-gain="${z?.gain||1}" aria-label="${square}: ${z?.kind==='energy'?'năng lượng':z?.kind==='control'?'kiểm soát':'thường'}" ${['a1','i9'].includes(square)?'disabled':''}><small>${square}</small><span>${z?.kind==='energy'?icon('bolt'):z?.kind==='control'?icon('target'):['a1','i9'].includes(square)?icon('home'):''}</span></button>`;}).join('')}</div><h3>Mẫu di chuyển bổ sung</h3><div id="rule-modifiers">${d.modifiers.map(modifierRow).join('')}</div>${button('Thêm mẫu đi','rule-add-modifier','','small')}<fieldset><legend>Kỹ năng Khiên</legend><label class="check-field"><input type="checkbox" name="shield-enabled" ${d.shield.enabled?'checked':''}>Bật Khiên · tiêu thụ một lượt để kích hoạt</label><div class="form-grid">${number('Chi phí Khiên','shield-cost',d.shield.cost,0,9)}${number('Thời hạn (lượt của đội)','shield-duration',d.shield.duration,1,5)}</div></fieldset><fieldset><legend>Điều kiện thắng</legend>${[['base_capture','Chiếm căn cứ'],['type_eliminated','Loại hết một loại quân'],['no_legal_moves','Đối thủ hết nước hợp lệ']].map(([k,l])=>`<label class="check-field"><input type="checkbox" name="victory-${k}" ${d.victory[k]?'checked':''}>${l}</label>`).join('')}${number('Điểm kiểm soát để thắng (0 = tắt)','control-target',d.victory.control_target,0,30)}<small>Hết toàn bộ quân luôn thua. Ưu tiên: căn cứ → hết quân → hết loại → kiểm soát → hết nước.</small></fieldset>${errors()}<div class="page-actions">${r&&['published','archived'].includes(r.status)?'<button type="submit" class="btn primary" disabled>Dùng Tạo phiên bản mới để sửa luật</button>':submit(r?'Lưu bản nháp':'Tạo bản nháp')}${button('Xem thử & kiểm tra','rule-preview')}${button('Xuất vào JSON','rule-export-editor')}</div><details class="rule-json"><summary>JSON nâng cao / nhập cấu hình</summary><textarea class="input mono" id="rule-json" rows="16" aria-label="JSON ruleset">${esc(JSON.stringify(d,null,2))}</textarea>${button('Áp dụng cấu hình JSON','rule-import-editor','','small')}</details></form>`;
}
export function readRuleForm(form){
 const v=name=>form.elements.namedItem(name)?.value,checked=name=>!!form.elements.namedItem(name)?.checked;
 return {schema_version:1,name:v('rule-name'),energy:{cap:Number(v('energy-cap')),initial:Number(v('energy-initial'))},
  zones:[...form.querySelectorAll('.rule-map-cell[data-kind]')].filter(b=>b.dataset.kind).map(b=>({square:b.dataset.square,kind:b.dataset.kind,gain:Number(b.dataset.gain)})),
  modifiers:[...form.querySelectorAll('[data-modifier]')].map(row=>{const i=row.dataset.modifier,ids=v('mod-'+i+'-ids').split(',').map(s=>s.trim()).filter(Boolean);return {id:v('mod-'+i+'-id'),filter:{kinds:kinds.filter(([k])=>checked('mod-'+i+'-'+k)).map(([k])=>k),...(ids.length?{piece_ids:ids}:{})},pattern:v('mod-'+i+'-pattern'),range:Number(v('mod-'+i+'-range')),cost:Number(v('mod-'+i+'-cost')),cooldown:Number(v('mod-'+i+'-cooldown'))};}),
  shield:{enabled:checked('shield-enabled'),cost:Number(v('shield-cost')),duration:Number(v('shield-duration'))},
  victory:{base_capture:checked('victory-base_capture'),type_eliminated:checked('victory-type_eliminated'),no_legal_moves:checked('victory-no_legal_moves'),control_target:Number(v('control-target'))}};
}
export function previewActionLabel(a,state){
 const p=state.board.flat().find(p=>p&&p.id===a.piece_id),kind=kinds.find(([k])=>k===p?.kind)?.[1]||'';
 return `${a.id} · ${a.type==='shield'?'Khiên · '+a.from:`${kind?kind+' ':''}${a.from} → ${a.to}${a.ability?' · '+a.ability:''}`} · ${a.energy_cost} năng lượng`;
}
export function rulePreviewMarkup(result,count=0,prefix='rule-preview'){
 if(!result)return empty('Xem thử bộ luật','Chọn Xem thử & kiểm tra để mô phỏng nước đi trước khi công bố.');
 const {observation:o,validation:v}=result,s=o.state;
 return `${badge('attention','Experimental')}${note(v.summary)}${v.warnings.map(note).join('')}<div class="rule-preview-resources">${['red','blue'].map(side=>`<span class="${side}">${side==='red'?'Đỏ':'Xanh'} · Năng lượng ${s.energy[side]} · Kiểm soát ${s.control[side]}</span>`).join('')}</div><div class="rule-map preview-map" role="img" aria-label="Xem thử bàn cờ nước ${s.ply}">${s.board.flat().map((p,i)=>{const square=String.fromCharCode(97+i%9)+(9-Math.floor(i/9)),z=o.zones.find(z=>z.square===square);return `<div class="rule-map-cell ${z?'zone-'+z.kind:''}" title="${square}${p?' · '+p.side+' · '+p.kind:''}"><small>${square}</small>${p?`<span class="log-piece ${p.side}">${pieceIcon(p.kind)}</span>`:z?`<span>${z.kind==='energy'?icon('bolt'):icon('target')}</span>`:''}</div>`;}).join('')}</div><p>Nước ${s.ply} · ${s.to_move==='red'?'Đỏ':'Xanh'} tới lượt · ${o.legal_actions.length} nước đi hợp lệ</p>${s.result?note(resultLabel(s.result)):`<label class="field"><span>Chọn nước đi để thử</span>${select('preview-action',o.legal_actions.map(a=>[a.id,previewActionLabel(a,s)]))}</label>${button('Thực hiện nước đi',prefix+'-step',count>=32?'disabled':'','primary')}`}${button('Về thế ban đầu',prefix+'-reset','','small')}${count>=32?note('Đã đủ 32 bước. Về thế ban đầu để thử chuỗi khác.'):''}<details class="addon-details"><summary>Observation hiện tại · ID, cooldown và Khiên</summary><pre class="report-json">${esc(JSON.stringify(o,null,2))}</pre></details>${result.events.length?`<pre class="report-json">${esc(JSON.stringify(result.events,null,2))}</pre>`:''}`;
}
